(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.011+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.012+sy*0.008+t*0.5)*6 + Math.cos(sy*0.01-t*0.4)*4;
  const w2y = Math.cos(sy*0.014-sx*0.006-t*0.45)*6 + Math.sin(sx*0.009+t*0.35)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*45, 0.055, 2.8, 1.15],
    [200+Math.sin(t*0.25+6)*110, 30+Math.cos(t*0.45)*70, 0.075, 2.4, 0.92]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.cos(d*f*0.5-t*sp*0.3+2.8)*w*0.5;
  }
  const nw = 9;
  const act=aS/nw, inh=iS/nw, cor=cS/nw;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0)+Math.sin(fx*0.05+fy*0.01-t*0.5))/3;
  const turb = Math.sin(fx*0.08+Math.sin(fy*0.06+t*0.8)*2+t*1.5)*Math.cos(fy*0.07+Math.sin(fx*0.05-t*0.6)*2+t*1.2)*0.4;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.5;
  const spiral = (sp1+sp2+sp3)/2.5;
  const micro = Math.sin(fx*0.22+t*0.9)*Math.sin(fy*0.22-t*0.7)*0.3+Math.sin((fx-fy)*0.15+t*1.3)*0.2;
  const reaction = Math.tanh((act-inh*0.65+cor*0.4+bg*0.25+spiral*0.35+turb*0.2+micro*0.15)*2.0);
  const lap = Math.sin(fx*0.18)*Math.sin(fy*0.18)+Math.sin(fx*0.13+fy*0.13+t*0.4)*0.7;
  const cell = Math.tanh(lap*1.8)*0.25;
  const blend = reaction*0.65+cell*0.35;
  const pulse = 0.92+Math.sin(t*0.8)*0.08;
  const v = blend*0.5*pulse+0.5;
  const pal = [
    [5,12,55],[8,35,85],[12,65,120],[18,105,135],
    [35,155,150],[90,185,130],[180,195,80],
    [220,170,60],[215,125,65],[195,80,70],
    [155,50,75],[100,30,65],[50,18,55],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const glow=Math.max(0,reaction*0.3);
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)*0.0012;
  const lum=(0.85+Math.sin(reaction*Math.PI)*0.15)*edge*vig;
  return [
    Math.min(255,Math.max(0,(r0*lum+glow*40)|0)),
    Math.min(255,Math.max(0,(g0*lum+glow*25)|0)),
    Math.min(255,Math.max(0,(b0*lum+glow*50)|0))
  ];
}
